//
// Entry point for the test plugin. Ribbon panel "Test" on tab "Instrumenty CRPR"
// is described by NC_TestRibbon.json and generated by NcBootstrap —
// this tool does not change the profile itself.
//

namespace NcTestRibbon
{
  using System;
  using System.IO;
  using System.Reflection;
  using NcTestRibbon.Cad;
  using Teigha.Runtime;

  public class Plugin : IExtensionApplication
  {
    public void Initialize()
    {
      // nanoCAD LoadFile probing often misses NuGet deps next to the plugin DLL.
      AppDomain.CurrentDomain.AssemblyResolve += OnAssemblyResolve;
    }

    public void Terminate()
    {
      try
      {
        CadSegmentBlinker.Stop();
      }
      catch
      {
      }

      try
      {
        CadPadOverlay.Clear();
      }
      catch
      {
      }

      AppDomain.CurrentDomain.AssemblyResolve -= OnAssemblyResolve;
    }

    private static Assembly OnAssemblyResolve(object sender, ResolveEventArgs args)
    {
      try
      {
        var requested = new AssemblyName(args.Name).Name;
        if (string.IsNullOrEmpty(requested))
        {
          return null;
        }

        var dir = Path.GetDirectoryName(typeof(Plugin).Assembly.Location);
        if (string.IsNullOrEmpty(dir))
        {
          return null;
        }

        var candidate = Path.Combine(dir, requested + ".dll");
        if (File.Exists(candidate))
        {
          return Assembly.LoadFrom(candidate);
        }
      }
      catch
      {
        // Ignore resolve failures; let the runtime continue probing.
      }

      return null;
    }
  }
}
